import{_ as e,o as i,c as l,a0 as r}from"./chunks/framework.ZP6uZ4uc.js";const u=JSON.parse('{"title":"Week 10: 预测 + 优化 Capstone","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"phase5-research/week10/index.md","filePath":"phase5-research/week10/index.md","lastUpdated":null}'),t={name:"phase5-research/week10/index.md"};function o(n,a,s,h,c,d){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="week-10-预测-优化-capstone" tabindex="-1">Week 10: 预测 + 优化 Capstone <a class="header-anchor" href="#week-10-预测-优化-capstone" aria-label="Permalink to &quot;Week 10: 预测 + 优化 Capstone&quot;">​</a></h1><h2 id="核心目标" tabindex="-1">核心目标 <a class="header-anchor" href="#核心目标" aria-label="Permalink to &quot;核心目标&quot;">​</a></h2><p>把预测模型输出转化为优化模型输入，比较不同信息质量下的决策表现。</p><hr><h2 id="本周问题" tabindex="-1">本周问题 <a class="header-anchor" href="#本周问题" aria-label="Permalink to &quot;本周问题&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">核心问题</p><p>预测更准确是否一定带来更好的决策？如何衡量预测误差对决策的影响？</p></div><hr><h2 id="必学内容" tabindex="-1">必学内容 <a class="header-anchor" href="#必学内容" aria-label="Permalink to &quot;必学内容&quot;">​</a></h2><h3 id="_1-capstone-概览" tabindex="-1">1. Capstone 概览 <a class="header-anchor" href="#_1-capstone-概览" aria-label="Permalink to &quot;1. Capstone 概览&quot;">​</a></h3><ul><li>科研问题链</li><li>项目目标</li><li>最终成果要求</li></ul><h3 id="_2-集成层" tabindex="-1">2. 集成层 <a class="header-anchor" href="#_2-集成层" aria-label="Permalink to &quot;2. 集成层&quot;">​</a></h3><ul><li><strong>数据层</strong>：数据集选择与处理</li><li><strong>预测层</strong>：模型与评价</li><li><strong>优化层</strong>：决策模型</li><li><strong>实验层</strong>：策略对比</li></ul><h3 id="_3-最终报告" tabindex="-1">3. 最终报告 <a class="header-anchor" href="#_3-最终报告" aria-label="Permalink to &quot;3. 最终报告&quot;">​</a></h3><ul><li>报告结构</li><li>展示要求</li><li>合格 vs 优秀标准</li></ul><hr><h2 id="本周产出" tabindex="-1">本周产出 <a class="header-anchor" href="#本周产出" aria-label="Permalink to &quot;本周产出&quot;">​</a></h2><h3 id="milestone-10-预测输出接入优化模型" tabindex="-1">Milestone 10：预测输出接入优化模型 <a class="header-anchor" href="#milestone-10-预测输出接入优化模型" aria-label="Permalink to &quot;Milestone 10：预测输出接入优化模型&quot;">​</a></h3><p><strong>通过标准：</strong></p><ul><li>两种预测进入完全相同的优化模型</li><li>在真实测试需求上计算最终运营成本</li><li>不只比较预测指标，还比较决策指标</li><li>包含 no-action benchmark 与 perfect-information benchmark</li></ul><p><strong>交付物：</strong></p><ul><li>完整的 Capstone 项目</li><li>最终报告</li></ul><hr><h2 id="research-thinking" tabindex="-1">Research Thinking <a class="header-anchor" href="#research-thinking" aria-label="Permalink to &quot;Research Thinking&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Research Thinking</p><p><strong>Why Negative Results Matter？当预测更准却没有带来更好决策时，这一结果说明了什么？</strong></p></div><hr><h2 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h2><ul><li><a href="./capstone-overview">Capstone 概览</a></li><li><a href="./data-layer">数据层</a></li><li><a href="./prediction-layer">预测层</a></li><li><a href="./optimization-layer">优化层</a></li><li><a href="./experiments">实验层</a></li><li><a href="./final-report">最终报告</a></li><li><a href="./exercises">练习题</a></li></ul><hr><h2 id="上一步" tabindex="-1">上一步 <a class="header-anchor" href="#上一步" aria-label="Permalink to &quot;上一步&quot;">​</a></h2><p>👈 <a href="./../../phase4-robustness/week9/">Week 9: 网络优化</a></p>',30)])])}const k=e(t,[["render",o]]);export{u as __pageData,k as default};
